export const isBrush=p=>p?.type==='hairbrush'&&p.brushProfile?.reviewed===true;
const ease=t=>{const x=Math.max(0,Math.min(1,t));return x*x*x*(x*(x*6-15)+10);};
// Inspect only: hands follow one rigid, unheated brush. No hair or scalp treatment.
export function brushHold(profile,time,reduced=false,rest){
 const t=Number.isFinite(time)?Math.max(0,time):0,reach=reduced?1:ease(t/.85)*(1-ease((t-3.5)/.9)),turn=reduced?.24:t<1?0:t<2?.55*ease(t-1):t<2.4?.55:t<3.4?.55*(1-ease(t-2.4)):0;
 const h=profile.lengthIn*2*.4,w=profile.widthIn*2*.4,co=Math.cos(turn),si=Math.sin(turn),grips=[{x:-.5,y:h*.18,z:0},{x:w*.48,y:h*.72,z:0}];
 const hands=grips.map((p,i)=>{const a=rest?.[i]||{x:(i?1:-1)*10,y:22,z:1.5},b={x:p.x*co,y:28+p.y,z:10-p.x*si};return{x:a.x+(b.x-a.x)*reach,y:a.y+(b.y-a.y)*reach,z:a.z+(b.z-a.z)*reach};});
 const centerX=grips.reduce((a,p)=>a+p.x,0)/2,centerY=grips.reduce((a,p)=>a+p.y,0)/2;
 return {reach,turn,hands,baseX:(hands[0].x+hands[1].x)/2-centerX*co,baseY:(hands[0].y+hands[1].y)/2-centerY,z:(hands[0].z+hands[1].z)/2+centerX*si,visible:reduced||reach>.02};
}
export function brushFactsHTML(p,esc){if(!isBrush(p))return '';const a=p.brushProfile;return `<section class="brush-facts frame-facts"><h4>Selected brush reference</h4><p>SKU <strong>${esc(p.referenceSKU)}</strong> · one ${esc(a.format.toLowerCase())}. Published length × width: <strong>${esc(a.lengthIn)} × ${esc(a.widthIn)} inches</strong>.</p><p>Wooden paddle and handle, dark cushion and extended pins. The source explains the intentionally missing pin as a ventilation/drainage opening.</p><p>${esc(p.sourceOfferNote)}</p><details><summary>Photograph & model notes</summary><p>${esc(a.photoBasis)}</p><p>The original solid model follows the published length-to-width ratio. Depth, contour, cushion, pin layout and wood grain are adapted game art. Inspection turns the brush without touching hair or skin; it does not change your hairstyle or simulate treatment results.</p></details></section>`;}
export function brushNotebookHTML(st,esc){return `<div class="modal-body brush-notebook"><span class="eyebrow">SOURCE NOTEBOOK · FREE TO READ</span><h3>Full size or mini?</h3><p>Compare the published dimensions and dated offers for these two individual brushes. Reading and choosing a card are free and pause time. Inspection uses six game minutes.</p><div class="brush-note-grid">${st.products.filter(isBrush).map(p=>`<article><h3>${esc(p.brushProfile.format)}</h3><p>${esc(p.brushProfile.lengthIn)} × ${esc(p.brushProfile.widthIn)} inches · SKU ${esc(p.referenceSKU)}</p><p>${esc(p.sourceOfferNote)}</p><button class="button secondary wide" data-action="detail" data-id="${esc(p.id)}">Inspect ${esc(p.brushProfile.format.toLowerCase())}</button></article>`).join('')}</div><p class="hint">Each reference is one brush. Hair results and branch inventory are not simulated from these source descriptions.</p><button class="button secondary" data-action="collection-open">Back to the collection desk</button></div>`;}
